//! Diff edge cases (docs/gitlab-ref/edge-cases-mr-diffs.md): renames and copies, sort order, mode
//! changes, empty and newline-less files, binaries and encodings, collapse/too_large limits and
//! generated files, through every diff endpoint.

use base64::Engine;
use labrat_conformance::Scenario;
use reqwest::Method;
use serde_json::{Value, json};

const GET: Method = Method::GET;
const POST: Method = Method::POST;

fn b64(bytes: &[u8]) -> String {
    base64::engine::general_purpose::STANDARD.encode(bytes)
}

fn lines(prefix: &str, n: usize) -> String {
    (1..=n).map(|i| format!("{prefix} line {i:04}\n")).collect()
}

/// `n` lines, with every line whose number is divisible by `every` changed.
fn changed(prefix: &str, n: usize, every: usize) -> String {
    (1..=n)
        .map(|i| if i % every == 0 { format!("{prefix} CHANGED {i:04}\n") } else { format!("{prefix} line {i:04}\n") })
        .collect()
}

#[tokio::test]
async fn mr_diff_edges() {
    let mut s = Scenario::new("mr_diff_edges").await;
    let admin = s.admin();
    let gpath = s.name("de");
    let g = s.step("group", POST, "/groups", Some(&admin), json!({"name": gpath, "path": gpath}), "namespace").await;
    let p = s.step("project", POST, "/projects", Some(&admin), json!({"name": "app", "namespace_id": g.id(), "initialize_with_readme": true}), "project").await;
    let pid = p.id();
    s.settle().await;
    let commits = format!("/projects/{pid}/repository/commits");
    // Files on main that the MRs rename, copy, delete or mark as generated.
    s.step(
        "base",
        POST,
        &commits,
        Some(&admin),
        json!({"branch": "main", "commit_message": "Base", "actions": [
            {"action": "create", "file_path": "r/a.txt", "content": lines("a", 20)},
            {"action": "create", "file_path": "r/b.txt", "content": lines("b", 20)},
            {"action": "create", "file_path": "r/c.txt", "content": lines("c", 20)},
            {"action": "create", "file_path": "r/copy-src.txt", "content": lines("s", 20)},
            {"action": "create", "file_path": "mode/x.sh", "content": "echo hi\n"},
            {"action": "create", "file_path": "empty/old.txt", "content": ""},
            {"action": "create", "file_path": "bin/old.dat", "content": b64(b"x\0y\n"), "encoding": "base64"},
            {"action": "create", "file_path": "enc/crlf.txt", "content": "a\r\nb\r\n"},
            {"action": "create", "file_path": "enc/noeol.txt", "content": "abc"},
            {"action": "create", "file_path": "enc/ws.txt", "content": "\tindented\n"},
            {"action": "create", "file_path": ".gitattributes", "content": "gen/attr.txt gitlab-generated\ngen/lin.txt linguist-generated\ngen/off.js -linguist-generated\n"},
            {"action": "create", "file_path": "gen/mod.txt", "content": "// Code generated by tool. DO NOT EDIT.\nold\n"},
        ]}),
        "commit",
    )
    .await;
    s.settle().await;

    let png: &[u8] = &[0x89, b'P', b'N', b'G', 0x0d, 0x0a, 0x1a, 0x0a, 0, 0, 0, 0x0d, b'I', b'H', b'D', b'R', 0, 0, 0, 1];
    let mut late_nul = vec![b'a'; 9000];
    late_nul.extend_from_slice(b"\0\n");
    let utf16: Vec<u8> = [0xffu8, 0xfe].into_iter().chain("hello\n".encode_utf16().flat_map(|u| u.to_le_bytes())).collect();
    let long_line = format!("{}\n", "x".repeat(150_000));

    let branches: Vec<(&str, Value)> = vec![
        // Renames, copies, sorting, modes, empty files, newlines.
        (
            "shapes",
            json!([
                {"action": "move", "previous_path": "r/a.txt", "file_path": "r/a2.txt"},
                {"action": "move", "previous_path": "r/b.txt", "file_path": "r/b2.txt", "content": changed("b", 20, 3)},
                {"action": "move", "previous_path": "r/c.txt", "file_path": "r/c2.txt", "content": changed("c", 20, 1)},
                {"action": "create", "file_path": "r/copy-dst.txt", "content": lines("s", 20)},
                {"action": "chmod", "file_path": "mode/x.sh", "execute_filemode": true},
                {"action": "create", "file_path": "empty/new.txt", "content": ""},
                {"action": "delete", "file_path": "empty/old.txt"},
                {"action": "update", "file_path": "enc/noeol.txt", "content": "abc\n"},
                {"action": "create", "file_path": "b.txt", "content": "1\n"},
                {"action": "create", "file_path": "B/x", "content": "1\n"},
                {"action": "create", "file_path": "a/z.txt", "content": "1\n"},
                {"action": "create", "file_path": "a/b/c.txt", "content": "1\n"},
                {"action": "create", "file_path": "A.txt", "content": "1\n"},
                {"action": "create", "file_path": "_u.txt", "content": "1\n"},
                {"action": "create", "file_path": "a.d/f", "content": "1\n"},
                {"action": "create", "file_path": "a/ä.txt", "content": "1\n"},
            ]),
        ),
        // Binaries and encodings.
        (
            "binary",
            json!([
                {"action": "create", "file_path": "bin/new.png", "content": b64(png), "encoding": "base64"},
                {"action": "create", "file_path": "bin/utf16.txt", "content": b64(&utf16), "encoding": "base64"},
                {"action": "create", "file_path": "bin/late-nul.txt", "content": b64(&late_nul), "encoding": "base64"},
                {"action": "delete", "file_path": "bin/old.dat"},
                {"action": "create", "file_path": "enc/latin1.txt", "content": b64(b"caf\xe9\n"), "encoding": "base64"},
                {"action": "create", "file_path": "enc/bad.txt", "content": b64(b"ok\n\xff\xfe\xfa\nok\n"), "encoding": "base64"},
                {"action": "update", "file_path": "enc/crlf.txt", "content": "a\r\nc\r\n"},
                {"action": "update", "file_path": "enc/ws.txt", "content": "    indented\n"},
                {"action": "create", "file_path": "enc/long.txt", "content": long_line},
            ]),
        ),
        // Size limits: a ~21 KB patch collapses, a >200 KiB patch is too large, and many lines in
        // total collapse the files after the crossing point.
        (
            "limits",
            json!([
                {"action": "create", "file_path": "limits/big20k.txt", "content": lines("twenty-k", 700)},
                {"action": "create", "file_path": "limits/huge.txt", "content": lines("huge", 7000)},
                {"action": "create", "file_path": "limits/m01.txt", "content": lines("m01", 600)},
                {"action": "create", "file_path": "limits/m02.txt", "content": lines("m02", 600)},
                {"action": "create", "file_path": "limits/m03.txt", "content": lines("m03", 600)},
                {"action": "create", "file_path": "limits/m04.txt", "content": lines("m04", 600)},
                {"action": "create", "file_path": "limits/m05.txt", "content": lines("m05", 600)},
                {"action": "create", "file_path": "limits/m06.txt", "content": lines("m06", 600)},
                {"action": "create", "file_path": "limits/m07.txt", "content": lines("m07", 600)},
                {"action": "create", "file_path": "limits/m08.txt", "content": lines("m08", 600)},
                {"action": "create", "file_path": "limits/m09.txt", "content": lines("m09", 600)},
                {"action": "create", "file_path": "limits/m10.txt", "content": lines("m10", 600)},
            ]),
        ),
        // Generated files.
        (
            "generated",
            json!([
                {"action": "create", "file_path": "gen/attr.txt", "content": "a\n"},
                {"action": "create", "file_path": "gen/lin.txt", "content": "a\n"},
                {"action": "create", "file_path": "gen/off.js", "content": "a\n"},
                {"action": "create", "file_path": "package-lock.json", "content": "{}\n"},
                {"action": "create", "file_path": "yarn.lock", "content": "x\n"},
                {"action": "create", "file_path": "app.min.js", "content": "x\n"},
                {"action": "create", "file_path": "x.pb.go", "content": "package x\n"},
                {"action": "create", "file_path": "own/f.txt", "content": "a\n"},
                {"action": "update", "file_path": ".gitattributes", "content": "gen/attr.txt gitlab-generated\ngen/lin.txt linguist-generated\ngen/off.js -linguist-generated\nown/f.txt gitlab-generated\n"},
                {"action": "update", "file_path": "gen/mod.txt", "content": "plain now\n"},
            ]),
        ),
    ];
    // An LFS pointer whose object was never uploaded fails the pre-receive LFS check.
    let pointer = format!("version https://git-lfs.github.com/spec/v1\noid sha256:{}\nsize 123\n", "a".repeat(64));
    s.step("lfs pointer", POST, &commits, Some(&admin), json!({"branch": "lfs", "start_branch": "main", "commit_message": "LFS", "actions": [{"action": "create", "file_path": "bin/lfs.txt", "content": pointer}]}), "commit").await;
    let mrs = format!("/projects/{pid}/merge_requests");
    for (i, (branch, actions)) in branches.iter().enumerate() {
        let iid = i as i64 + 1;
        let c = s
            .step(&format!("{branch} commit"), POST, &commits, Some(&admin), json!({"branch": branch, "start_branch": "main", "commit_message": format!("{branch} changes"), "actions": actions}), "commit")
            .await;
        let sha = c.get("id").as_str().unwrap_or_default().to_string();
        s.settle().await;
        s.step(&format!("{branch} mr"), POST, &mrs, Some(&admin), json!({"source_branch": branch, "target_branch": "main", "title": format!("{branch}")}), "mr").await;
        s.poll_mr(pid, iid).await;
        let mr = format!("{mrs}/{iid}");
        s.step(&format!("{branch} show"), GET, &mr, Some(&admin), json!(null), "mr").await;
        s.step(&format!("{branch} diffs"), GET, &format!("{mr}/diffs"), Some(&admin), json!({"per_page": 100}), "diff").await;
        s.step(&format!("{branch} diffs page 1 of 1"), GET, &format!("{mr}/diffs"), Some(&admin), json!({"per_page": 1}), "diff").await;
        s.step(&format!("{branch} diffs page 2 of 1"), GET, &format!("{mr}/diffs"), Some(&admin), json!({"per_page": 1, "page": 2}), "diff").await;
        s.step(&format!("{branch} changes"), GET, &format!("{mr}/changes"), Some(&admin), json!(null), "mr").await;
        s.step(&format!("{branch} changes unidiff"), GET, &format!("{mr}/changes"), Some(&admin), json!({"unidiff": true}), "mr").await;
        s.step(&format!("{branch} changes raw"), GET, &format!("{mr}/changes"), Some(&admin), json!({"access_raw_diffs": true}), "mr").await;
        let versions = s.step(&format!("{branch} versions"), GET, &format!("{mr}/versions"), Some(&admin), json!(null), "version").await;
        if let Some(v) = versions.body.as_array().and_then(|a| a.first()).and_then(|v| v["id"].as_i64()) {
            s.step(&format!("{branch} version"), GET, &format!("{mr}/versions/{v}"), Some(&admin), json!(null), "version").await;
        }
        s.step(&format!("{branch} raw diffs"), GET, &format!("{mr}/raw_diffs"), Some(&admin), json!(null), "diff").await;
        s.step(&format!("{branch} compare"), GET, &format!("/projects/{pid}/repository/compare"), Some(&admin), json!({"from": "main", "to": branch}), "compare").await;
        s.step(&format!("{branch} commit diff"), GET, &format!("/projects/{pid}/repository/commits/{sha}/diff"), Some(&admin), json!({"per_page": 100}), "diff").await;
        s.graphql(
            &format!("{branch} graphql stats"),
            Some(&admin),
            "query($p: ID!, $iid: String!) { project(fullPath: $p) { mergeRequest(iid: $iid) { diffStatsSummary { additions deletions changes fileCount } diffStats { path additions deletions } } } }",
            json!({"p": format!("{gpath}/app"), "iid": iid.to_string()}),
        )
        .await;
    }
    s.finish();
}
